import json
import pandas as pd
import pdfplumber

# Paths
pdf_path = '/root/employees_backup.pdf'
excel_path = '/root/employees_current.xlsx'
output_path = '/root/diff_report.json'

# Extract tables from PDF
all_tables = []
with pdfplumber.open(pdf_path) as pdf:
    for page in pdf.pages:
        tables = page.extract_tables()
        for table in tables:
            if table and len(table) > 1:
                df = pd.DataFrame(table[1:], columns=table[0])
                all_tables.append(df)

if not all_tables:
    old_df = pd.DataFrame()
else:
    old_df = pd.concat(all_tables, ignore_index=True)

# Read Excel
new_df = pd.read_excel(excel_path, engine='openpyxl')

# Ensure ID column exists and is string
id_col_candidates = [c for c in ['ID', 'Id', 'Employee ID', 'EmployeeID'] if c in old_df.columns]
if id_col_candidates:
    old_id_col = id_col_candidates[0]
else:
    raise KeyError('ID column not found in PDF data')

new_id_col_candidates = [c for c in ['ID', 'Id', 'Employee ID', 'EmployeeID'] if c in new_df.columns]
if new_id_col_candidates:
    new_id_col = new_id_col_candidates[0]
else:
    raise KeyError('ID column not found in Excel data')

old_df = old_df.rename(columns={old_id_col: 'ID'})
new_df = new_df.rename(columns={new_id_col: 'ID'})
old_df['ID'] = old_df['ID'].astype(str)
new_df['ID'] = new_df['ID'].astype(str)

# Deleted employees
old_ids = set(old_df['ID'])
new_ids = set(new_df['ID'])
deleted = sorted(list(old_ids - new_ids))

# Modified employees
common_ids = old_ids & new_ids
modified = []
# Determine columns to compare (exclude ID)
compare_cols = [c for c in old_df.columns if c != 'ID']
for emp_id in sorted(common_ids):
    old_row = old_df[old_df['ID'] == emp_id].iloc[0]
    new_row = new_df[new_df['ID'] == emp_id].iloc[0]
    for col in compare_cols:
        if col not in new_row:
            continue
        old_val = old_row[col]
        new_val = new_row[col]
        # Treat NaN as missing
        if pd.isna(old_val) and pd.isna(new_val):
            continue
        if pd.isna(old_val) or pd.isna(new_val) or old_val != new_val:
            # Convert numeric strings to numbers if possible
            def convert(val):
                if isinstance(val, str):
                    try:
                        if '.' in val:
                            return float(val)
                        else:
                            return int(val)
                    except ValueError:
                        return val
                return val
            old_conv = convert(old_val)
            new_conv = convert(new_val)
            modified.append({
                'id': emp_id,
                'field': col,
                'old_value': old_conv,
                'new_value': new_conv
            })

# Sort modified by id then field
modified.sort(key=lambda x: (x['id'], x['field']))

report = {
    'deleted_employees': deleted,
    'modified_employees': modified
}

with open(output_path, 'w') as f:
    json.dump(report, f, indent=2)
